#!/usr/bin/env bash
# Rasterize apps/viewer/build/icon.svg into apps/viewer/build/icon.icns.
#
# The .icns is committed, and this script is what regenerates it. Two reasons it
# is not built as part of `bun run dist`:
#
#   * The build runs in CI (release.yml) on a runner with no SVG rasterizer, and
#     the icon is not worth a Homebrew install per job.
#   * The bundle is signed, so what ships has to be a fixed input rather than
#     something regenerated by whatever librsvg the builder happens to have.
#
# So: edit icon.svg, run this, commit both. Nothing else reads the SVG.
#
# Needs rsvg-convert (`brew install librsvg`); `iconutil` ships with macOS.
# rsvg-convert rather than sips or qlmanage because neither reads SVG at all —
# sips is a raster converter, and qlmanage renders a *preview*, at whatever size
# and with whatever padding Quick Look feels like.
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
svg="$here/icon.svg"
icns="$here/icon.icns"

[ "$(uname -s)" = Darwin ] || { echo "iconutil is macOS-only" >&2; exit 1; }
command -v rsvg-convert >/dev/null || {
  echo "error: rsvg-convert not found — brew install librsvg" >&2
  exit 1
}

# mktemp, not a path in the repo: a failed run must not leave a half-built
# iconset behind for the next one to fold into the .icns.
work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT
iconset="$work/AppIcon.iconset"
mkdir -p "$iconset"

# The ten files iconutil expects, by name. Each logical size twice — @1x and the
# @2x of the size below it — so one .icns covers Retina and non-Retina.
for size in 16 32 128 256 512; do
  rsvg-convert -w "$size" -h "$size" "$svg" -o "$iconset/icon_${size}x${size}.png"
  double=$((size * 2))
  rsvg-convert -w "$double" -h "$double" "$svg" -o "$iconset/icon_${size}x${size}@2x.png"
done

iconutil --convert icns --output "$icns" "$iconset"
echo ">> wrote $icns ($(stat -f%z "$icns") bytes)"
